import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Plus, Edit2, Trash2, Eye, ArrowLeft } from 'lucide-react';
import './AdminPanel.css';

function AdminPanel({ posts, onAddPost, onDeletePost, onEditPost }) {
  const navigate = useNavigate();
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    excerpt: '',
    content: '',
    category: 'Technology',
    image: '',
    readingTime: 5,
    tags: '',
  });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: name === 'readingTime' ? parseInt(value) : value,
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const tags = formData.tags
      .split(',')
      .map((tag) => tag.trim())
      .filter((tag) => tag);

    if (editingId) {
      onEditPost(editingId, {
        ...formData,
        tags,
      });
      setEditingId(null);
    } else {
      onAddPost({
        ...formData,
        tags,
      });
    }

    setFormData({
      title: '',
      excerpt: '',
      content: '',
      category: 'Technology',
      image: '',
      readingTime: 5,
      tags: '',
    });
    setIsFormOpen(false);
  };

  const handleEdit = (post) => {
    setFormData({
      title: post.title,
      excerpt: post.excerpt,
      content: post.content,
      category: post.category,
      image: post.image,
      readingTime: post.readingTime,
      tags: post.tags.join(', '),
    });
    setEditingId(post.id);
    setIsFormOpen(true);
  };

  const handleCancel = () => {
    setIsFormOpen(false);
    setEditingId(null);
    setFormData({
      title: '',
      excerpt: '',
      content: '',
      category: 'Technology',
      image: '',
      readingTime: 5,
      tags: '',
    });
  };

  return (
    <div className="admin-panel">
      <div className="admin-header">
        <button className="admin-back-btn" onClick={() => navigate('/')}>
          <ArrowLeft size={20} />
        </button>
        <div>
          <h1>Admin Panel</h1>
          <p>Manage blog posts and content</p>
        </div>
        <button
          className="btn-primary"
          onClick={() => setIsFormOpen(!isFormOpen)}
        >
          <Plus size={18} />
          {isFormOpen ? 'Cancel' : 'New Post'}
        </button>
      </div>

      {isFormOpen && (
        <motion.form
          className="post-form"
          onSubmit={handleSubmit}
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -20 }}
        >
          <h2>{editingId ? 'Edit Post' : 'Create New Post'}</h2>

          <div className="form-group">
            <label>Title</label>
            <input
              type="text"
              name="title"
              value={formData.title}
              onChange={handleInputChange}
              placeholder="Post title"
              required
            />
          </div>

          <div className="form-group">
            <label>Excerpt</label>
            <textarea
              name="excerpt"
              value={formData.excerpt}
              onChange={handleInputChange}
              placeholder="Brief summary of the post"
              rows={2}
              required
            />
          </div>

          <div className="form-row">
            <div className="form-group">
              <label>Category</label>
              <select
                name="category"
                value={formData.category}
                onChange={handleInputChange}
              >
                <option>Technology</option>
                <option>Architecture</option>
                <option>DevOps</option>
                <option>Frontend</option>
                <option>Security</option>
                <option>Database</option>
              </select>
            </div>

            <div className="form-group">
              <label>Reading Time (minutes)</label>
              <input
                type="number"
                name="readingTime"
                value={formData.readingTime}
                onChange={handleInputChange}
                min="1"
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label>Image URL</label>
            <input
              type="url"
              name="image"
              value={formData.image}
              onChange={handleInputChange}
              placeholder="https://..."
              required
            />
          </div>

          <div className="form-group">
            <label>Tags (comma-separated)</label>
            <input
              type="text"
              name="tags"
              value={formData.tags}
              onChange={handleInputChange}
              placeholder="react, javascript, tutorial"
            />
          </div>

          <div className="form-group">
            <label>Content</label>
            <textarea
              name="content"
              value={formData.content}
              onChange={handleInputChange}
              placeholder="Full post content (markdown supported)"
              rows={10}
              required
            />
          </div>

          <div className="form-actions">
            <button type="submit" className="btn-primary">
              {editingId ? 'Update Post' : 'Publish Post'}
            </button>
            <button
              type="button"
              className="btn-secondary"
              onClick={handleCancel}
            >
              Cancel
            </button>
          </div>
        </motion.form>
      )}

      <div className="posts-table">
        <table>
          <thead>
            <tr>
              <th>Title</th>
              <th>Category</th>
              <th>Date</th>
              <th>Reading Time</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {posts.map((post) => (
              <tr key={post.id}>
                <td>
                  <strong>{post.title}</strong>
                </td>
                <td>
                  <span className="category-badge">{post.category}</span>
                </td>
                <td>{post.date}</td>
                <td>{post.readingTime} min</td>
                <td>
                  <div className="action-buttons">
                    <button
                      className="action-btn view"
                      title="View"
                      onClick={() => navigate(`/post/${post.id}`)}
                    >
                      <Eye size={16} />
                    </button>
                    <button
                      className="action-btn edit"
                      title="Edit"
                      onClick={() => handleEdit(post)}
                    >
                      <Edit2 size={16} />
                    </button>
                    <button
                      className="action-btn delete"
                      title="Delete"
                      onClick={() => {
                        if (
                          window.confirm(
                            'Are you sure you want to delete this post?'
                          )
                        ) {
                          onDeletePost(post.id);
                        }
                      }}
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default AdminPanel;
